import React, { useState, type ReactNode } from 'react';
import { apiErrorMessage } from '../utils/apiError';
import styles from './services/Services.module.css';

// Moldura dos formulários do painel do admin: título, erro, "Nada mudou.", "Salvando..." e
// "Cancelar". Usada pelos formulários de serviço (SPEC/2026-11-23-painel-servicos.md) e de
// barbeiro (SPEC/2026-11-26-painel-barbeiros.md). Quem usa cuida só dos campos.

type Props = {
  title: string;
  /** Texto do botão de salvar. Enquanto salva, vira "Salvando...". */
  submitLabel: string;
  /** Mensagem quando a API falha sem dizer o motivo. */
  errorFallback: string;
  /** Confere os campos antes da API: a mensagem do problema, ou null. */
  validate: () => string | null;
  /**
   * Grava. Devolve false quando não havia nada para gravar (o formulário diz "Nada mudou.").
   * Quem chamou fecha o formulário depois de salvar.
   */
  save: () => Promise<boolean>;
  onCancel: () => void;
  children: ReactNode;
};

const AdminForm = ({ title, submitLabel, errorFallback, validate, save, onCancel, children }: Props) => {
  const [error, setError] = useState('');
  const [info, setInfo] = useState('');
  const [saving, setSaving] = useState(false);

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();
    setError('');
    setInfo('');

    const problem = validate();
    if (problem) {
      setError(problem);
      return;
    }

    setSaving(true);
    try {
      if (!(await save())) {
        setInfo('Nada mudou.');
        setSaving(false);
      }
    } catch (err) {
      setError(apiErrorMessage(err, errorFallback));
      setSaving(false);
    }
  };

  return (
    <form className={styles.form} onSubmit={handleSubmit} noValidate aria-label={title}>
      <h3>{title}</h3>

      {children}

      {error && <p className={styles.error} role="alert">{error}</p>}
      {info && <p className={styles.info} role="status">{info}</p>}

      <div className={styles.actions}>
        <button type="button" className={styles.secondary} onClick={onCancel} disabled={saving}>
          Cancelar
        </button>
        <button type="submit" className={styles.primary} disabled={saving}>
          {saving ? 'Salvando...' : submitLabel}
        </button>
      </div>
    </form>
  );
};

/** Um campo do formulário: rótulo e controle, em meia linha ou na linha inteira (`wide`). */
export const FormField = ({ id, label, wide = false, children }: {
  id: string;
  label: string;
  wide?: boolean;
  children: ReactNode;
}) => (
  <div className={wide ? `${styles.field} ${styles.wide}` : styles.field}>
    <label htmlFor={id}>{label}</label>
    {children}
  </div>
);

/** Selo de situação das linhas do painel: "Ativo" ou "Desativado". */
export const StatusBadge = ({ active }: { active: boolean }) => (
  <span className={`${styles.badge} ${active ? styles.badgeActive : styles.badgeInactive}`}>
    {active ? 'Ativo' : 'Desativado'}
  </span>
);

export default AdminForm;
import { useState, useEffect } from 'react';
import { useNavigate, Routes, Route, Link, useLocation } from 'react-router-dom';
import styles from './Dashboard.module.css';
import api, { logout } from '../api';
import { canFinish } from '../utils/appointmentStatus';
import { CHANGE_PASSWORD_PATH } from '../utils/afterLogin';

import AdminStore from './AdminStore';
import AdminServices from './AdminServices';
import AdminFinance from './AdminFinance';
import AdminExpenses from './AdminExpenses';
import AdminNotifications from './AdminNotifications';
import AdminUsers from './AdminUsers';
import AdminBarbers from './AdminBarbers';
import Account from './Account';

const Overview = ({ user }: { user: any }) => {
  const [queue, setQueue] = useState<any[]>([]);
  const [appointments, setAppointments] = useState<any[]>([]);
  const [stats, setStats] = useState<any>({ total_revenue: 0, completed_appointments: 0 });

  useEffect(() => {
    if (!user) return;

    if (user.role === 'admin') {
      // Busca dados do dashboard
      api.get('/reports/daily-overview').then(res => {
        setStats(res.data);
      }).catch(console.error);

      // Busca fila
      api.get('/queue/live').then(res => {
        setQueue(res.data);
      }).catch(console.error);
    } else if (user.role === 'barber') {
      api.get('/reports/me').then(res => {
        setStats({ 
          total_revenue: res.data.total_revenue_generated, 
          completed_appointments: res.data.total_appointments 
        });
      }).catch(console.error);

      api.get('/appointments/barber/me').then(res => {
        setAppointments(res.data);
      }).catch(console.error);
    }
  }, [user]);

  return (
    <>
      <div className={styles.header}>
        <h2 className={styles.title}>Bem-vindo(a), {user?.full_name || 'Admin'}!</h2>
      </div>
      <div className={styles.statsGrid}>
        <div className={styles.statCard}>
          <div className={styles.statTitle}>Faturamento (Hoje)</div>
          <div className={`${styles.statValue} ${styles.statHighlight}`}>R$ {Number(stats.total_revenue).toFixed(2)}</div>
        </div>
        <div className={styles.statCard}>
          <div className={styles.statTitle}>Cortes Finalizados</div>
          <div className={styles.statValue}>{stats.completed_appointments}</div>
        </div>
      </div>

      {user.role === 'admin' && (
        <div className={styles.queueSection}>
          <h3 className={styles.queueTitle}>Fila de Espera (Ao Vivo)</h3>
          {queue.length === 0 ? (
            <p style={{ color: 'var(--color-text-secondary)' }}>Nenhum cliente na fila.</p>
          ) : (
            <div className={styles.queueList}>
              {queue.map((item: any, idx: number) => (
                <div key={idx} className={styles.queueItem}>
                  <div className={styles.queueInfo}>
                    <h4>{item.customer_name_masked}</h4>
                    <p>Posição {item.position} • Entrou às {new Date(item.joined_at).toLocaleTimeString()}</p>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {user.role === 'barber' && (
        <div className={styles.queueSection}>
          <h3 className={styles.queueTitle}>Meus Agendamentos (Hoje)</h3>
          {appointments.length === 0 ? (
            <p style={{ color: 'var(--color-text-secondary)' }}>Nenhum agendamento para hoje.</p>
          ) : (
            <div className={styles.queueList}>
              {appointments.filter((a: any) => new Date(a.start_datetime).toDateString() === new Date().toDateString()).map((item: any) => (
                <div key={item.id} className={styles.queueItem} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <div className={styles.queueInfo}>
                    <h4>{item.notes ? item.notes : 'Cliente'}</h4>
                    <p>{item.start_datetime.substring(11, 16)} • {item.status}</p>
                  </div>
                  {canFinish(item) && (
