import { useCallback } from 'react';
import api from '../api';
import { useApiResource } from './useApiResource';

// Despesas e categorias do painel do admin (SPEC/2026-11-26-painel-despesas.md), sobre as rotas
// de /expenses (SPEC/2026-11-25-despesas-validacoes.md). As ações devolvem o que o backend
// gravou e lançam o erro da API, para quem chamou mostrar a mensagem.

export type ExpenseCategory = { id: string; name: string; created_at: string };

export type Expense = {
  id: string;
  category_id: string | null;
  description: string;
  /** O backend serializa o Decimal como texto, com 2 casas ("100.50"). */
  amount: string;
  /** "AAAA-MM-DD" */
  payment_date: string;
  is_recurring: boolean;
  created_at: string;
  updated_at: string;
  category: ExpenseCategory | null;
};

/** Campos da criação, já no formato da API. */
export type ExpenseInput = Pick<Expense, 'category_id' | 'description' | 'amount' | 'payment_date' | 'is_recurring'>;
/** Alteração parcial: só os campos que mudaram. */
export type ExpenseChanges = Partial<ExpenseInput>;

/** Período da lista, em "AAAA-MM-DD". Vazio não filtra. */
export type Period = { start: string; end: string };

const byName = (a: ExpenseCategory, b: ExpenseCategory) =>
  a.name.localeCompare(b.name, 'pt-BR', { sensitivity: 'base' });

/** Mesma ordem do backend: data do pagamento mais recente primeiro. */
const byDateDesc = (a: Expense, b: Expense) => b.payment_date.localeCompare(a.payment_date);

/** Põe `saved` na lista, no lugar do item de mesmo id ou como novo, e ordena. */
function upsert<T extends { id: string }>(list: T[], saved: T, order: (a: T, b: T) => number): T[] {
  return [...list.filter((item) => item.id !== saved.id), saved].sort(order);
}

const loadCategories = async () => (await api.get<ExpenseCategory[]>('/expenses/categories')).data;

export function useExpenseCategories() {
  const { data: categories, setData, status, loadError, reload } = useApiResource(
    loadCategories,
    [] as ExpenseCategory[],
    'Não foi possível carregar as categorias.',
  );

  const store = useCallback((saved: ExpenseCategory) => {
    setData((current) => upsert(current, saved, byName));
    return saved;
  }, []);

  const createCategory = useCallback(
    async (name: string) => store((await api.post<ExpenseCategory>('/expenses/categories', { name })).data),
    [store],
  );

  const renameCategory = useCallback(
    async (id: string, name: string) =>
      store((await api.put<ExpenseCategory>(`/expenses/categories/${id}`, { name })).data),
    [store],
  );

  const deleteCategory = useCallback(async (id: string) => {
    await api.delete(`/expenses/categories/${id}`);
    setData((current) => current.filter((c) => c.id !== id));
  }, []);

  return { categories, status, loadError, reload, createCategory, renameCategory, deleteCategory };
}

export function useAdminExpenses({ start, end }: Period) {
  const load = useCallback(async () => {
    const params: Record<string, string> = {};
    if (start) params.start_date = start;
    if (end) params.end_date = end;
    return (await api.get<Expense[]>('/expenses', { params })).data;
  }, [start, end]);

  const { data: expenses, setData, status, loadError, reload } = useApiResource(
    load,
    [] as Expense[],
    'Não foi possível carregar as despesas.',
  );

  const store = useCallback((saved: Expense) => {
    setData((current) => upsert(current, saved, byDateDesc));
    return saved;
  }, []);

  const createExpense = useCallback(
    async (input: ExpenseInput) => store((await api.post<Expense>('/expenses', input)).data),
    [store],
  );

  const updateExpense = useCallback(
    async (id: string, changes: ExpenseChanges) => store((await api.put<Expense>(`/expenses/${id}`, changes)).data),
    [store],
  );

  const deleteExpense = useCallback(async (id: string) => {
    await api.delete(`/expenses/${id}`);
    setData((current) => current.filter((e) => e.id !== id));
  }, []);

  /**
   * Leva para as despesas da lista a categoria renomeada, ou tira a categoria apagada (`null`):
   * o backend já fez o mesmo (`ON DELETE SET NULL`), e a lista não precisa ser carregada de novo.
   */
  const syncCategory = useCallback((id: string, category: ExpenseCategory | null) => {
    setData((current) =>
      current.map((e) =>
        e.category_id === id ? { ...e, category, category_id: category ? category.id : null } : e,
      ),
    );
  }, []);

  return { expenses, status, loadError, reload, createExpense, updateExpense, deleteExpense, syncCategory };
}
import React, { useState } from 'react';
import shared from '../../pages/AdminShared.module.css';
import LoadState, { ActionFeedback } from '../LoadState';
import type { ExpenseCategory, useExpenseCategories } from '../../hooks/useAdminExpenses';
import { useRowAction } from '../../hooks/useRowAction';
import { validateCategoryName } from '../../utils/expenseValidation';
import CategoryRow from './CategoryRow';

// Gestão das categorias de despesa, na tela de despesas (SPEC/2026-11-26-painel-despesas.md):
// criar, renomear e excluir. O nome é conferido antes da API; a recusa da API (nome repetido)
// aparece no topo da seção.

type Props = {
  resource: ReturnType<typeof useExpenseCategories>;
  /** A categoria foi renomeada (com o nome novo) ou excluída (null): a lista de despesas acompanha. */
  onChanged: (id: string, category: ExpenseCategory | null) => void;
};

const ExpenseCategories = ({ resource, onChanged }: Props) => {
  const { categories, status, loadError, reload, createCategory, renameCategory, deleteCategory } = resource;
  const { busyId, message, actionError, run, clear } = useRowAction();
  const [newName, setNewName] = useState('');
  const [invalid, setInvalid] = useState('');

  /** Confere o nome antes da API. Devolve false (e mostra o erro) quando não serve. */
  const check = (name: string) => {
    clear();
    const problem = validateCategoryName(name);
    setInvalid(problem ?? '');
    return problem === null;
  };

  const add = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!check(newName)) return;
    if (await run('new', () => createCategory(newName.trim()), 'Categoria criada.')) setNewName('');
  };

  const rename = async (category: ExpenseCategory, name: string) => {
    if (!check(name)) return false;
    const saved = await run(category.id, () => renameCategory(category.id, name.trim()), 'Categoria renomeada.');
    if (saved) onChanged(category.id, saved);
    return saved !== undefined;
  };

  const remove = async (category: ExpenseCategory) => {
    setInvalid('');
    const done = await run(category.id, async () => {
      await deleteCategory(category.id);
      return true;
    }, 'Categoria excluída.');
    if (done) onChanged(category.id, null);
  };

  return (
    <section aria-label="Categorias" style={{ marginTop: '2.5rem' }}>
      <h3 className={shared.title}>Categorias</h3>

      <form className={shared.filters} onSubmit={add} noValidate>
        <input aria-label="Nova categoria" placeholder="Nova categoria" value={newName} onChange={(e) => setNewName(e.target.value)} />
        <button type="submit" className={shared.btnAction} disabled={status !== 'ready' || busyId === 'new'}>
          Adicionar
        </button>
      </form>

      <ActionFeedback message={message} error={invalid || actionError} />

      <LoadState status={status} loadError={loadError} reload={reload} loadingText="Carregando categorias...">
        {categories.length === 0 ? (
          <p>Nenhuma categoria cadastrada.</p>
        ) : (
          <table className={shared.table}>
            <thead>
              <tr>
                <th>Categoria</th>
                <th>Ações</th>
              </tr>
            </thead>
            <tbody>
              {categories.map((category) => (
                <CategoryRow
                  key={category.id}
                  category={category}
                  busy={busyId === category.id}
                  onRename={rename}
                  onDelete={remove}
                />
              ))}
            </tbody>
          </table>
        )}
      </LoadState>
    </section>
  );
};

export default ExpenseCategories;
import { useState } from 'react';
import shared from '../../pages/AdminShared.module.css';
import ConfirmButton from '../ConfirmButton';
import type { ExpenseCategory } from '../../hooks/useAdminExpenses';

// Uma linha da lista de categorias de despesa (SPEC/2026-11-26-painel-despesas.md): "Renomear"
// troca o nome pelo campo na própria linha; "Excluir" pede confirmação.

type Props = {
  category: ExpenseCategory;
  busy: boolean;
  /** Grava o nome novo. Devolve true quando gravou, para a linha sair da edição. */
  onRename: (category: ExpenseCategory, name: string) => Promise<boolean>;
  onDelete: (category: ExpenseCategory) => void;
};

const CategoryRow = ({ category, busy, onRename, onDelete }: Props) => {
  // null: fora da edição.
  const [name, setName] = useState<string | null>(null);

  const save = async () => {
    if (name !== null && (await onRename(category, name))) setName(null);
  };

  if (name !== null) {
    return (
      <tr aria-label={category.name}>
        <td>
          <input aria-label={`Novo nome de ${category.name}`} value={name} onChange={(e) => setName(e.target.value)} />
        </td>
        <td>
          <button className={shared.btnIcon} onClick={save} disabled={busy}>Salvar</button>
          <button className={shared.btnIcon} onClick={() => setName(null)} disabled={busy}>Cancelar</button>
        </td>
      </tr>
    );
  }

  return (
    <tr aria-label={category.name}>
      <td style={{ color: '#fff', fontWeight: 500 }}>{category.name}</td>
      <td>
        <ConfirmButton
          label="Excluir"
          question="Excluir a categoria? As despesas ficam sem categoria."
          onConfirm={() => onDelete(category)}
          busy={busy}
        >
          <button className={shared.btnIcon} onClick={() => setName(category.name)} disabled={busy}>
            Renomear
          </button>
        </ConfirmButton>
      </td>
    </tr>
  );
};

export default CategoryRow;
import { useState, type ReactNode } from 'react';
import shared from '../pages/AdminShared.module.css';

// Ação destrutiva com confirmação no próprio lugar: o botão vira a pergunta, "Confirmar" e
// "Voltar". Usado em "Desativar" serviço (SPEC/2026-11-23-painel-servicos.md) e em "Cancelar"
// agendamento (SPEC/2026-11-25-meus-agendamentos.md).

type Props = {
  /** Texto do botão que abre a confirmação. */
  label: string;
  /** Nome acessível do botão, quando o texto sozinho não basta (vários na mesma tela). */
  ariaLabel?: string;
  /** Pergunta mostrada no lugar do botão. */
  question: string;
  onConfirm: () => void;
  /** Uma ação está em andamento: os botões ficam desabilitados. */
  busy?: boolean;
  /** Outras ações, mostradas ao lado do botão e escondidas durante a confirmação. */
  children?: ReactNode;
};

const ConfirmButton = ({ label, ariaLabel, question, onConfirm, busy = false, children }: Props) => {
  const [confirming, setConfirming] = useState(false);

  if (confirming) {
    return (
      <>
        <span className={shared.confirmQuestion}>{question}</span>
        <button
          type="button"
          className={`${shared.btnIcon} ${shared.btnDanger}`}
          onClick={() => {
            setConfirming(false);
            onConfirm();
          }}
          disabled={busy}
        >
          Confirmar
        </button>
        <button type="button" className={shared.btnIcon} onClick={() => setConfirming(false)} disabled={busy}>
          Voltar
        </button>
      </>
    );
  }

  return (
    <>
      {children}
      <button
        type="button"
        className={`${shared.btnIcon} ${shared.btnDanger}`}
        aria-label={ariaLabel}
        onClick={() => setConfirming(true)}
        disabled={busy}
      >
        {label}
      </button>
    </>
  );
};

export default ConfirmButton;
import type { ReactNode } from 'react';
import type { LoadStatus } from '../hooks/useApiResource';
import shared from '../pages/AdminShared.module.css';
import styles from './services/Services.module.css';

// Estado da carga de uma tela do painel (useApiResource): "carregando", o erro com "Tentar de
// novo", ou o conteúdo. E as mensagens do resultado de uma ação (useRowAction). Usado pelos
// painéis de serviços e de usuários (SPEC/2026-11-25-admin-usuarios.md).

type Props = {
  status: LoadStatus;
  loadError: string;
  reload: () => void;
  /** Texto enquanto carrega. */
  loadingText: string;
  children: ReactNode;
};

const LoadState = ({ status, loadError, reload, loadingText, children }: Props) => {
  if (status === 'loading') return <p>{loadingText}</p>;
  if (status === 'error') {
    return (
      <div>
        <p className={styles.error} role="alert">{loadError}</p>
        <button type="button" className={shared.btnAction} onClick={reload}>Tentar de novo</button>
      </div>
    );
  }
  return <>{children}</>;
};

/** Mensagem de sucesso e erro de uma ação, no topo da tela. */
export const ActionFeedback = ({ message, error }: { message: string; error: string }) => (
  <>
    {message && <p className={styles.info} role="status">{message}</p>}
    {error && <p className={styles.error} role="alert">{error}</p>}
  </>
);

export default LoadState;
// Perfis de acesso e os nomes deles na tela: "Minha conta" (SPEC/2026-11-22-auth-perfil-senha.md)
// e o painel de usuários (SPEC/2026-11-25-admin-usuarios.md).

export type UserRole = 'admin' | 'barber' | 'client';

export const ROLE_LABELS: Record<UserRole, string> = {
  admin: 'Administrador',
  barber: 'Barbeiro',
  client: 'Cliente',
};

/** Os perfis na ordem em que aparecem nos seletores. */
export const ROLES = Object.keys(ROLE_LABELS) as UserRole[];
import { isAxiosError } from 'axios';

type ValidationIssue = { msg?: string };

/**
 * Mensagem em português para mostrar ao usuário a partir de um erro da API.
 * O 422 do FastAPI traz uma lista de problemas ({ msg }), com o prefixo "Value error, "
 * nas validações escritas no backend; os outros erros trazem `detail` como texto.
 */
export function apiErrorMessage(error: unknown, fallback = 'Não foi possível concluir. Tente de novo.'): string {
  if (!isAxiosError(error)) return fallback;
  if (!error.response) return 'Sem conexão com o servidor. Verifique a internet e tente de novo.';
  const detail = (error.response.data as { detail?: unknown } | undefined)?.detail;
  if (typeof detail === 'string' && detail) return detail;
  if (Array.isArray(detail)) {
    const messages = detail
      .map((issue: ValidationIssue) => (issue?.msg ?? '').replace(/^Value error, /, ''))
      .filter(Boolean);
    if (messages.length) return messages.join(' | ');
  }
  return fallback;
}

