});

export const ALUGUEL = expenseCategory('Aluguel');
export const LUZ = expenseCategory('Luz');

export function makeExpense(id: string, extra: Partial<Expense> = {}, category: ExpenseCategory | null = null): Expense {
  return {
    id,
