  mockedGet.mockImplementation((url: string) => {
    if (url === '/auth/me') return Promise.resolve({ data: user });
    if (url === '/auth/users') {
      return Promise.resolve({ data: { users: [], total: 0, page: 1, per_page: 20, total_pages: 0 } });
    }
    return Promise.resolve({ data: [] });
  });
