    expect((await screen.findByRole('alert')).textContent).toBe('Categoria não encontrada.');
    await waitFor(() => expect(names()).toEqual(['Aluguel', 'Luz']));
    expect(onChanged).not.toHaveBeenCalled();
  });
});

