const OLD = makePhoto('p1', { created_at: '2026-11-10T10:00:00Z' });
const NEW = makePhoto('p2', { created_at: '2026-11-22T10:00:00Z' });
const LIVE = makePhoto('p3', { is_approved: true, created_at: '2026-11-15T10:00:00Z' });

