    await waitFor(() => expect(mocked.get).toHaveBeenLastCalledWith('/gallery', { params: {} }));
  });

  it('falha sem mensagem usa o texto padrão', async () => {
    mocked.get.mockRejectedValue(httpError(500));
    const { result } = renderHook(() => usePublicGallery(''));

